// Demo: a Pathfinder message into RabbitMQ, as the Router would send it.
// Flowfile -> RabbitMQ message over AMQP 1.0, unchanged (ADR 0007; NiFi's PublishAMQP speaks only 0-9-1).
// Address = exchange + the routingKey attribute. message-id, correlation-id, content-type and reply-to come from the
// amqp$ attributes, durable from amqp$deliveryMode = 2. Attributes that match headers.pattern become
// application-properties. A flowfile goes to success only when RabbitMQ accepted its message, else to failure.
import com.rabbitmq.client.amqp.Publisher
import com.rabbitmq.client.amqp.Resource
import com.rabbitmq.client.amqp.impl.AmqpEnvironmentBuilder
import groovy.transform.Field
import java.util.concurrent.CompletableFuture
import java.util.concurrent.TimeUnit
import java.util.regex.Pattern
import org.apache.nifi.processor.ProcessContext

@Field static final long OUTCOME_SECONDS = 30
@Field static environment = null
@Field static publisher = null

static synchronized connect(ProcessContext context) {
    if (publisher?.state() == Resource.State.OPEN) return publisher
    disconnect()
    def p = { String name -> context.getProperty(name).getValue() }
    environment = new AmqpEnvironmentBuilder().build()
    publisher = environment.connectionBuilder()
            .host(p('rabbitmq.host')).port(p('rabbitmq.port') as int).virtualHost(p('rabbitmq.vhost'))
            .username(p('rabbitmq.user')).password(p('rabbitmq.password'))
            .name(p('connection.name'))                    // shown in the RabbitMQ UI and checked by BridgeTest ping
            .recovery().activated(false).connectionBuilder() // a broken connection is made again on the next run
            .build()
            .publisherBuilder().build()
    publisher
}

static synchronized void disconnect() {
    try { environment?.close() } catch (ignored) { }
    environment = null
    publisher = null
}

// Connect at start, not at the first flowfile, so an idle Bridge still shows its connection (BridgeTest ping checks it).
static void onStart(ProcessContext context) {
    try { connect(context) } catch (e) { disconnect(); throw e }
}

static void onStop(ProcessContext context) { disconnect() }
static void onUnscheduled(ProcessContext context) { disconnect() }

def toMessage(out, flowFile, String exchange, Pattern headers) {
    def a = flowFile.getAttributes()
    if (!a.routingKey) throw new IllegalArgumentException('no routingKey attribute')
    def message = out.message(session.read(flowFile).withCloseable { it.bytes })
    message.durable(a['amqp$deliveryMode'] == '2')
    if (a['amqp$messageId']) message.messageId(a['amqp$messageId'])
    if (a['amqp$correlationId']) message.correlationId(a['amqp$correlationId'])
    if (a['amqp$contentType']) message.contentType(a['amqp$contentType'])
    if (a['amqp$replyTo']) message.replyTo(a['amqp$replyTo'])
    a.each { k, v -> if (headers.matcher(k).matches()) message.property(k, v) }
    message.toAddress().exchange(exchange).key(a.routingKey).message()
}

def flowFiles = session.get(100)
if (!flowFiles) return
def exchange = context.getProperty('exchange').getValue()
def headers = Pattern.compile(context.getProperty('headers.pattern').getValue())
try {
    def out = connect(context)
    def sent = []
    flowFiles.each { flowFile ->
        def message
        try {
            message = toMessage(out, flowFile, exchange, headers)
        } catch (e) {                                     // this message cannot be sent; let the others go on
            log.error('Cannot make an AMQP message from {}, sent to failure', flowFile, e)
            session.transfer(session.penalize(flowFile), REL_FAILURE)
            return
        }
        def outcome = new CompletableFuture()
        out.publish(message, { ctx -> outcome.complete(ctx.status()) } as Publisher.Callback)
        sent << [flowFile, outcome]
    }
    def deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(OUTCOME_SECONDS)
    sent.each { flowFileAndOutcome ->
        def (flowFile, outcome) = flowFileAndOutcome
        def status = outcome.get(Math.max(0L, deadline - System.nanoTime()), TimeUnit.NANOSECONDS)
        if (status == Publisher.Status.ACCEPTED) {
            session.transfer(flowFile, REL_SUCCESS)
        } else {
            log.error('RabbitMQ did not accept {} ({}), sent to failure', flowFile, status)
            session.transfer(session.penalize(flowFile), REL_FAILURE)
        }
    }
} catch (e) {
    disconnect()                                          // no outcome in time or a broken connection: all tried again
    throw e
}

