// B-03: RabbitMQ -> Solace.
// RabbitMQ queue -> flowfiles over AMQP 1.0, unchanged (ADR 0007; NiFi's ConsumeAMQP speaks only 0-9-1).
// Writes the attributes ConsumeAMQP wrote, so the next step is unchanged: consume.amqp.<name> per
// application-property, amqp$routingKey from the x-routing-key annotation, amqp$messageId, amqp$correlationId,
// amqp$contentType and amqp$replyTo. Content = the body bytes. A message is accepted on RabbitMQ only after NiFi
// has stored its flowfile; if that fails, or the connection drops first, RabbitMQ delivers it again.
import com.rabbitmq.client.amqp.Consumer
import com.rabbitmq.client.amqp.Message
import com.rabbitmq.client.amqp.Resource
import com.rabbitmq.client.amqp.impl.AmqpEnvironmentBuilder
import groovy.transform.Field
import java.util.concurrent.LinkedBlockingQueue
import org.apache.nifi.processor.ProcessContext
import org.apache.nifi.processor.io.OutputStreamCallback

@Field static final String PREFIX = 'consume.amqp.'
@Field static final int CREDITS = 100                     // messages RabbitMQ may hand over before NiFi stored them
@Field static final LinkedBlockingQueue inbox = new LinkedBlockingQueue()
@Field static environment = null
@Field static consumer = null

static synchronized void connect(ProcessContext context) {
    if (consumer?.state() == Resource.State.OPEN) return
    disconnect()
    def p = { String name -> context.getProperty(name).getValue() }
    environment = new AmqpEnvironmentBuilder().build()
    consumer = environment.connectionBuilder()
            .host(p('rabbitmq.host')).port(p('rabbitmq.port') as int).virtualHost(p('rabbitmq.vhost'))
            .username(p('rabbitmq.user')).password(p('rabbitmq.password'))
            .name(p('connection.name'))                    // shown in the RabbitMQ UI and checked by BridgeTest ping
            .recovery().activated(false).connectionBuilder() // a broken connection is made again on the next run
            .build()
            .consumerBuilder().queue(p('queue')).initialCredits(CREDITS)
            .messageHandler({ ctx, message -> inbox.put([ctx, message]) } as Consumer.MessageHandler)
            .build()
}

static synchronized void disconnect() {
    try { environment?.close() } catch (ignored) { }
    environment = null
    consumer = null
    inbox.clear()                                         // never accepted, so RabbitMQ delivers them again
}

static void onStop(ProcessContext context) { disconnect() }
static void onUnscheduled(ProcessContext context) { disconnect() }

static void settle(List received, boolean accept, logger) {
    received.each { ctxAndMessage ->
        try {
            accept ? ctxAndMessage[0].accept() : ctxAndMessage[0].requeue()
        } catch (e) {                                     // the connection dropped: RabbitMQ delivers it again
            logger.warn('Cannot {} a RabbitMQ message, it will be delivered again', accept ? 'accept' : 'requeue', e)
        }
    }
}

def toFlowFile(message) {
    def a = [:]
    message.forEachProperty { k, v -> if (v != null) a[PREFIX + k] = v.toString() }
    [
        'amqp$routingKey'   : message.annotation('x-routing-key'),
        'amqp$messageId'    : message.messageId(),
        'amqp$correlationId': message.correlationId(),
        'amqp$contentType'  : message.contentType(),
        'amqp$replyTo'      : message.replyTo(),
    ].each { k, v -> if (v != null) a[k] = v.toString() }
    def flowFile = session.putAllAttributes(session.create(), a)
    def relationship = REL_SUCCESS
    byte[] body
    try {
        body = message.body() ?: new byte[0]
    } catch (e) {                                         // a map or list body: kept in NiFi as text, not sent to Solace
        log.error('RabbitMQ message {} has no byte or text body, sent to failure', a['amqp$messageId'], e)
        body = String.valueOf(message.body({ it } as Message.Converter)).getBytes('UTF-8')
        relationship = REL_FAILURE
    }
    session.transfer(session.write(flowFile, { out -> out.write(body) } as OutputStreamCallback), relationship)
}

try {
    connect(context)
} catch (e) {
    disconnect()
    context.yield()
    throw e
}
def received = []
inbox.drainTo(received, CREDITS)
if (!received) {
    context.yield()
    return
}
def logger = log                                          // the script's bindings are cleared before the commit ends
try {
    received.each { toFlowFile(it[1]) }
} catch (e) {
    settle(received, false, logger)                       // RabbitMQ delivers them again at once, so wait first
    context.yield()
    throw e
}
session.commitAsync({ settle(received, true, logger) } as Runnable,
        { failure -> settle(received, false, logger) } as java.util.function.Consumer)

// B-03: RabbitMQ message -> Solace topic, unchanged.
// Topic = routing key with '.' -> '/'. Every RabbitMQ header becomes a JMS property, except VV_ROUTE,
// which only exists inside RabbitMQ. message-id and content-type become the properties messageId and
// contentType, correlation-id and reply-to the JMS fields. A reply-to that starts "q/" is a queue, any
// other a topic; the name is kept. PublishJMS cannot set such a reply-to, so this script publishes itself.
import groovy.transform.Field
import org.apache.nifi.processor.ProcessContext

@Field static final String PREFIX = 'consume.amqp.'
@Field static connection = null

static synchronized connect(factory, String user, String password) {
    if (connection == null) connection = factory.createConnection(user, password)
    connection
}

static synchronized void disconnect() {
    try { connection?.close() } catch (ignored) { }
    connection = null
}

static void onStop(ProcessContext context) { disconnect() }
static void onUnscheduled(ProcessContext context) { disconnect() }

def toJms(jms, flowFile) {
    def a = flowFile.getAttributes()
    def message = jms.createTextMessage(session.read(flowFile).withCloseable { it.getText('UTF-8') })
    a.each { k, v ->
        def name = k.startsWith(PREFIX) ? k.substring(PREFIX.length()) : null
        if (name && !name.contains('$') && name != 'VV_ROUTE') message.setStringProperty(name, v)
    }
    if (a['amqp$messageId']) message.setStringProperty('messageId', a['amqp$messageId'])
    if (a['amqp$contentType']) message.setStringProperty('contentType', a['amqp$contentType'])
    if (a['amqp$correlationId']) message.setJMSCorrelationID(a['amqp$correlationId'])
    def replyTo = a['amqp$replyTo']
    if (replyTo) message.setJMSReplyTo(replyTo.startsWith('q/') ? jms.createQueue(replyTo) : jms.createTopic(replyTo))
    [jms.createTopic(a['amqp$routingKey'].replace('.', '/')), message]
}

def flowFiles = session.get(100)
if (!flowFiles) return
def jms = null
try {
    def conn = connect(CTL.jms.getConnectionFactory(),
            context.getProperty('solace.user').getValue(), context.getProperty('solace.password').getValue())
    jms = conn.createSession(true, 0)                 // one transaction per batch: all sent or none
    def producer = jms.createProducer(null)
    producer.setDeliveryMode(2)                       // PERSISTENT
    flowFiles.each { flowFile ->
        def topicAndMessage
        try {
            topicAndMessage = toJms(jms, flowFile)
        } catch (e) {                                 // this message cannot be sent; let the others go on
            log.error('Cannot make a JMS message from {}, sent to failure', flowFile, e)
            session.transfer(session.penalize(flowFile), REL_FAILURE)
            return
        }
        producer.send(*topicAndMessage)
        session.transfer(flowFile, REL_SUCCESS)
    }
    jms.commit()
} catch (e) {
    disconnect()                                      // a broken connection is made again on the next run
    throw e
} finally {
    try { jms?.close() } catch (ignored) { }
}

// B-04: Solace message -> RabbitMQ properties, unchanged. Routing key = topic with '/' -> '.'.
// A property is set only when the Solace message has it: an empty one would reach RabbitMQ as "".
def flowFile = session.get()
if (!flowFile) return
def a = flowFile.getAttributes()
if (!a.jms_destination) {
    log.error('No jms_destination on {}, sent to failure', flowFile)
    session.transfer(session.penalize(flowFile), REL_FAILURE)
    return
}
def properties = [
    'amqp$messageId'    : a.messageId ?: a.jms_messageId,
    'amqp$correlationId': a.jms_correlationId,
    'amqp$contentType'  : a.contentType,
    'amqp$deliveryMode' : a.jms_deliveryMode,
    'amqp$replyTo'      : a.jms_replyTo,
].findAll { it.value }
properties.routingKey = a.jms_destination.replace('/', '.')
flowFile = session.putAllAttributes(flowFile, properties)
session.transfer(flowFile, REL_SUCCESS)
